def parse_text(text: str) -> dict:
    """
    一个存在缺陷的文本解析器
    """
    # split() 在面对空字符串或纯空白字符时，会返回一个空列表 []
    tokens = text.split()

    # 当输入为空或纯空白时，tokens 为空列表，返回默认值而不是访问索引 0
    if not tokens:
        return {
            "command": None,
            "argument": None
        }

    command = tokens[0]
    argument = tokens[1] if len(tokens) > 1 else None

    return {
        "command": command,
        "argument": argument
    }

